01259 {
01260     float u = 1.0f - t;
01261     float w1 = u * u * u;
01262     float w2 = 3 * u * u * t;
01263     float w3 = 3 * u * t * t;
01264     float w4 = t * t * t;
01265     return ImVec2(w1 * p1.x + w2 * p2.x + w3 * p3.x + w4 * p4.x, w1 * p1.y + w2 * p2.y + w3 * p3.y + w4 * p4.y);
01266 }

01269 {
01270     float u = 1.0f - t;
01271     float w1 = u * u;
01272     float w2 = 2 * u * t;
01273     float w3 = t * t;
01274     return ImVec2(w1 * p1.x + w2 * p2.x + w3 * p3.x, w1 * p1.y + w2 * p2.y + w3 * p3.y);
01275 }

03241 {
03242     // Render into our custom data blocks
03243     IM_ASSERT(atlas->TexPixelsAlpha8 != NULL || atlas->TexPixelsRGBA32 != NULL);
03244     ImFontAtlasBuildRenderDefaultTexData(atlas);
03245     ImFontAtlasBuildRenderLinesTexData(atlas);
03246 
03247     // Register custom rectangle glyphs
03248     for (int i = 0; i < atlas->CustomRects.Size; i++)
03249     {
03250         const ImFontAtlasCustomRect* r = &atlas->CustomRects[i];
03251         if (r->Font == NULL || r->GlyphID == 0)
03252             continue;
03253 
03254         // Will ignore ImFontConfig settings: GlyphMinAdvanceX, GlyphMinAdvanceY, GlyphExtraSpacing, PixelSnapH
03255         IM_ASSERT(r->Font->ContainerAtlas == atlas);
03256         ImVec2 uv0, uv1;
03257         atlas->CalcCustomRectUV(r, &uv0, &uv1);
03258         r->Font->AddGlyph(NULL, (ImWchar)r->GlyphID, r->GlyphOffset.x, r->GlyphOffset.y, r->GlyphOffset.x + r->Width, r->GlyphOffset.y + r->Height, uv0.x, uv0.y, uv1.x, uv1.y, r->GlyphAdvanceX);
03259     }
03260 
03261     // Build all fonts lookup tables
03262     for (ImFont* font : atlas->Fonts)
03263         if (font->DirtyLookupTables)
03264             font->BuildLookupTable();
03265 
03266     atlas->TexReady = true;
03267 }

03213 {
03214     // Round font size
03215     // - We started rounding in 1.90 WIP (18991) as our layout system currently doesn't support non-rounded font size well yet.
03216     // - Note that using io.FontGlobalScale or SetWindowFontScale(), with are legacy-ish, partially supported features, can still lead to unrounded sizes.
03217     // - We may support it better later and remove this rounding.
03218     for (ImFontConfig& cfg : atlas->ConfigData)
03219        cfg.SizePixels = ImTrunc(cfg.SizePixels);
03220 
03221     // Register texture region for mouse cursors or standard white pixels
03222     if (atlas->PackIdMouseCursors < 0)
03223     {
03224         if (!(atlas->Flags & ImFontAtlasFlags_NoMouseCursors))
03225             atlas->PackIdMouseCursors = atlas->AddCustomRectRegular(FONT_ATLAS_DEFAULT_TEX_DATA_W * 2 + 1, FONT_ATLAS_DEFAULT_TEX_DATA_H);
03226         else
03227             atlas->PackIdMouseCursors = atlas->AddCustomRectRegular(2, 2);
03228     }
03229 
03230     // Register texture region for thick lines
03231     // The +2 here is to give space for the end caps, whilst height +1 is to accommodate the fact we have a zero-width row
03232     if (atlas->PackIdLines < 0)
03233     {
03234         if (!(atlas->Flags & ImFontAtlasFlags_NoBakedLines))
03235             atlas->PackIdLines = atlas->AddCustomRectRegular(IM_DRAWLIST_TEX_LINES_WIDTH_MAX + 2, IM_DRAWLIST_TEX_LINES_WIDTH_MAX + 1);
03236     }
03237 }

02716 {
02717     for (unsigned int i = 0; i < 256; i++)
02718     {
02719         unsigned int value = (unsigned int)(i * in_brighten_factor);
02720         out_table[i] = value > 255 ? 255 : (value & 0xFF);
02721     }
02722 }

02725 {
02726     IM_ASSERT_PARANOID(w <= stride);
02727     unsigned char* data = pixels + x + y * stride;
02728     for (int j = h; j > 0; j--, data += stride - w)
02729         for (int i = w; i > 0; i--, data++)
02730             *data = table[*data];
02731 }

03071 {
03072     stbrp_context* pack_context = (stbrp_context*)stbrp_context_opaque;
03073     IM_ASSERT(pack_context != NULL);
03074 
03075     ImVector<ImFontAtlasCustomRect>& user_rects = atlas->CustomRects;
03076     IM_ASSERT(user_rects.Size >= 1); // We expect at least the default custom rects to be registered, else something went wrong.
03077 #ifdef __GNUC__
03078     if (user_rects.Size < 1) { __builtin_unreachable(); } // Workaround for GCC bug if IM_ASSERT() is defined to conditionally throw (see #5343)
03079 #endif
03080 
03081     ImVector<stbrp_rect> pack_rects;
03082     pack_rects.resize(user_rects.Size);
03083     memset(pack_rects.Data, 0, (size_t)pack_rects.size_in_bytes());
03084     for (int i = 0; i < user_rects.Size; i++)
03085     {
03086         pack_rects[i].w = user_rects[i].Width;
03087         pack_rects[i].h = user_rects[i].Height;
03088     }
03089     stbrp_pack_rects(pack_context, &pack_rects[0], pack_rects.Size);
03090     for (int i = 0; i < pack_rects.Size; i++)
03091         if (pack_rects[i].was_packed)
03092         {
03093             user_rects[i].X = (unsigned short)pack_rects[i].x;
03094             user_rects[i].Y = (unsigned short)pack_rects[i].y;
03095             IM_ASSERT(pack_rects[i].w == user_rects[i].Width && pack_rects[i].h == user_rects[i].Height);
03096             atlas->TexHeight = ImMax(atlas->TexHeight, pack_rects[i].y + pack_rects[i].h);
03097         }
03098 }

03111 {
03112     IM_ASSERT(x >= 0 && x + w <= atlas->TexWidth);
03113     IM_ASSERT(y >= 0 && y + h <= atlas->TexHeight);
03114     unsigned int* out_pixel = atlas->TexPixelsRGBA32 + x + (y * atlas->TexWidth);
03115     for (int off_y = 0; off_y < h; off_y++, out_pixel += atlas->TexWidth, in_str += w)
03116         for (int off_x = 0; off_x < w; off_x++)
03117             out_pixel[off_x] = (in_str[off_x] == in_marker_char) ? in_marker_pixel_value : IM_COL32_BLACK_TRANS;
03118 }

03101 {
03102     IM_ASSERT(x >= 0 && x + w <= atlas->TexWidth);
03103     IM_ASSERT(y >= 0 && y + h <= atlas->TexHeight);
03104     unsigned char* out_pixel = atlas->TexPixelsAlpha8 + x + (y * atlas->TexWidth);
03105     for (int off_y = 0; off_y < h; off_y++, out_pixel += atlas->TexWidth, in_str += w)
03106         for (int off_x = 0; off_x < w; off_x++)
03107             out_pixel[off_x] = (in_str[off_x] == in_marker_char) ? in_marker_pixel_value : 0x00;
03108 }

03058 {
